// Chapter strain: the tracks of its model over the slider, and what speckle tracking measures on
// the heart mesh along them (src/straintrack.js, the targets of src/gl/strainmesh.js).
//
// A track sets the weights of the targets at end-systole. kT is the LV wall's motion across the
// wall, and kL its shortening along the long axis. For the LAD territory, q is its share of the
// rest's motion, and k is the rest's. For apical sparing, p is the share of the shortening along the
// axis that the basal and mid levels lose, and u the share of their motion across it. The chapter
// scales them through the beat by the systolic weight s of the cycle model (cyclemodel.js).
//   global: every segment loses its function together, the shortening along the axis first. So GLS
//     falls while the LVEF holds; then the LVEF falls.
//   regional: the LAD territory goes from normal to akinetic while the other segments stay normal.
//     Then the other segments lose function too.
//   apical: apical sparing. The basal and mid segments lose their shortening along the axis while
//     the apical segments keep theirs, so GLS falls with a normal LVEF and the relative apical LS
//     rises past 1.0. Then the basal and mid segments lose their motion across the axis, and the
//     LVEF falls.
//   onco: the follow-up study of a patient during cancer therapy: GLS falls first, then the LVEF.
// TABLE holds, for each heart and track, at the slider positions 0, 0.05 ... 1: the strain of the
// 18 segments at end-systole (%), and the midline's length in each apical view at end-diastole and
// at end-systole (cm). It also holds the LV volumes by the biplane method of disks (mL). All are
// measured on the mesh (the method: README, "Checks run before this commit").
import { tracks } from './sev.js';

const T = {
  global: tracks([0, 0.2, 0.4, 0.6, 0.8, 1], {
    kL: [1, 0.80, 0.58, 0.47, 0.40, 0.37],
    kT: [1, 1.0, 0.90, 0.64, 0.42, 0.28],
  }),
  regional: tracks([0, 0.15, 0.3, 0.45, 0.6, 0.8, 1], {
    q: [1, 0.72, 0.45, 0.2, 0, 0, 0],
    k: [1, 1, 1, 1, 1, 0.73, 0.53],
  }),
  apical: tracks([0, 0.15, 0.3, 0.45, 0.6, 0.8, 1], {
    p: [0, 0.25, 0.45, 0.62, 0.72, 0.75, 0.78],
    u: [0, 0, 0, 0, 0.05, 0.4, 0.68],
  }),
  onco: tracks([0, 0.25, 0.5, 0.75, 1], {
    kL: [1, 0.86, 0.72, 0.56, 0.42],
    kT: [1, 0.99, 0.95, 0.62, 0.36],
  }),
};
export const TRACK_KEYS = Object.keys(T);

/** The targets' weights at end-systole on track at slider position x; a: the heart's amyloid burden. */
export function weightsAt(track, x, a = 0) {
  const m = T[track](Math.max(0, Math.min(1, x)));
  const w = track === 'regional'
    ? { strA: 1, strB: m.k, strD: m.k, strR: m.k * (1 - m.q) }
    : track === 'apical'
      ? { strA: 1, strB: 1, strD: 1, strP: m.p, strQ: m.u }
      : { strA: 1, strB: m.kT, strD: m.kL, strR: 0 };
  if (a) w.strZ = a;
  return w;
}

