/** The segments of the 18-segment model in the order the table holds them: [view, side, level]. */
export const SEGS = (() => {
  const out = [];
  for (const view of ['a4c', 'a2c', 'a3c']) for (const k of [0, 1, 2, 3, 4, 5]) out.push([view, k]);
  return out;
})();

/** The measured values of heart on track at slider position x, interpolated between nodes. */
export function measuredAt(heart, track, x) {
  const rows = (TABLE[heart] || TABLE.normal)?.[track];
  if (!rows) return null;
  const u = Math.max(0, Math.min(1, x)) * (NODES - 1), i = Math.min(NODES - 2, Math.floor(u)), f = u - i;
  const r = rows[i].map((v, k) => v + (rows[i + 1][k] - v) * f);
  return {
    segs: r.slice(0, 18).map((v) => v / 10),
    len0: r.slice(18, 21).map((v) => v / 1000),
    len1: r.slice(21, 24).map((v) => v / 1000),
    edv: r[24] / 10,
    esv: r[25] / 10,
  };
}
